div.script:
(function () {
  var a = document.querySelector('.anbn-wa'); if (!a) return;
  var p = location.pathname;
  /* en el pago no estorba: se oculta */
  if (/^\/shop\/(checkout|payment|confirmation|address|extra_info)/.test(p)) { a.remove(); return; }
  /* mensaje según la página: en la ficha de un anillo, el nombre y la liga de esa pieza */
  var h1 = document.querySelector('#product_details h1');
  var msg = h1 ? 'Hola Anello, me interesa el anillo «' + h1.textContent.trim() + '»: ' + location.origin + p
               : 'Hola Anello, vi su página anello.mx y me gustaría recibir información.';
  a.href = 'https://wa.me/' + a.dataset.wa + '?text=' + encodeURIComponent(msg);
  /* burbuja de saludo, una sola vez por visitante */
  var b = document.querySelector('.anbn-wa-bubble'), k = 'anbn_wa_bubble';
  var seen = false; try { seen = localStorage.getItem(k); } catch (e) {}
  /* horario de WhatsApp: 8:00 a 21:00 todos los días, hora del centro de México */
  try {
    var hr = +new Intl.DateTimeFormat('es-MX', { hour: 'numeric', hour12: false, timeZone: 'America/Mexico_City' }).format(new Date()) % 24;
    if ((hr < 8 || hr >= 21) && b) {
      b.querySelector('b').textContent = 'Déjanos tu mensaje';
      b.querySelector('.anbn-wa-txt').textContent = 'Ahora estamos fuera de horario. Escríbenos y te contestamos a partir de las 8:00.';
    }
  } catch (e) {}
  if (b && !seen) setTimeout(function () { b.hidden = false; }, 8000);
  function done() { if (b) b.hidden = true; try { localStorage.setItem(k, '1'); } catch (e) {} }
  if (b) { b.querySelector('button').addEventListener('click', done); b.addEventListener('click', function (e) { if (e.target.tagName !== 'BUTTON') { done(); a.click(); } }); }
  /* contador de clics (xb_whatsapp_web_leads) */
  window.anbnWaBeacon = function (kind) {
    try {
      var f = new FormData(); f.append('path', location.pathname); f.append('kind', kind);
      var t = document.querySelector('.js_main_product input.product_template_id, input[name=product_template_id]');
      if (t && t.value) f.append('product_tmpl_id', t.value);
      navigator.sendBeacon('/xb_wa/click', f);
    } catch (e) {}
  };
  a.addEventListener('click', function () { done(); window.anbnWaBeacon('float'); });
})();
